prog='''import numpy as np
from collections import Counter

def _sgn(v):
    return ( (v[0]>0)-(v[0]<0), (v[1]>0)-(v[1]<0) )

def transform(grid):
    g = np.array(grid)
    ones = np.argwhere(g == 1)
    r0, r1 = ones[:, 0].min(), ones[:, 0].max()
    c0, c1 = ones[:, 1].min(), ones[:, 1].max()
    sub = g[r0:r1 + 1, c0:c1 + 1]
    vals = Counter(sub[(sub != 0) & (sub != 1)].tolist())
    pattern_color = vals.most_common(1)[0][0]
    marks = np.argwhere((sub != 0) & (sub != 1) & (sub != pattern_color))
    mr0, mr1 = marks[:, 0].min(), marks[:, 0].max()
    mc0, mc1 = marks[:, 1].min(), marks[:, 1].max()
    crop = sub[max(0, mr0 - 1):mr1 + 2, max(0, mc0 - 1):mc1 + 2]
    mask = np.zeros(g.shape, bool)
    mask[r0:r1 + 1, c0:c1 + 1] = True
    dots = np.argwhere((g != 0) & ~mask)
    dpos = {int(g[r, c]): (int(r), int(c)) for r, c in dots}
    rows = [p[0] for p in dpos.values()]
    cols = [p[1] for p in dpos.values()]
    corner_col, cc = None, None
    for k, (r, c) in dpos.items():
        if rows.count(r) == 2 and cols.count(c) == 2:
            corner_col, cc = k, (r, c)
    target = {k: _sgn((r - cc[0], c - cc[1])) for k, (r, c) in dpos.items() if k != corner_col}
    variants = [crop, np.rot90(crop, 1), np.rot90(crop, 2), np.rot90(crop, 3),
                crop.T, np.rot90(crop.T, 1), np.rot90(crop.T, 2), np.rot90(crop.T, 3)]
    for v in variants:
        pos = {int(v[r, c]): (r, c) for r, c in np.argwhere((v != 0) & (v != 1) & (v != pattern_color))}
        if corner_col not in pos:
            continue
        r2, c2 = pos[corner_col]
        rel = {k: _sgn((int(r - r2), int(c - c2))) for k, (r, c) in pos.items() if k != corner_col}
        if rel == target:
            return v.tolist()
    return crop.tolist()
'''
